package com.modelrag.knowledge.controller;
import com.modelrag.common.cache.QaAnswerCache; import com.modelrag.common.dto.ApiResponse; import com.modelrag.common.event.ReembedDatasetEvent; import com.modelrag.common.outbox.IndexOutbox; import com.modelrag.common.security.AccessControlService; import com.modelrag.common.security.RequestUser; import com.modelrag.common.vector.VectorStore; import com.modelrag.knowledge.model.Dataset; import com.modelrag.knowledge.service.KnowledgeStore; import java.util.List; import java.util.Map; import org.springframework.context.ApplicationEventPublisher; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/knowledge-bases") public class KnowledgeBaseController {private final KnowledgeStore store;private final IndexOutbox outbox;private final QaAnswerCache answers;private final VectorStore vectors;private final ApplicationEventPublisher events;private final AccessControlService access;public KnowledgeBaseController(KnowledgeStore s,IndexOutbox o,QaAnswerCache a,VectorStore v,ApplicationEventPublisher e,AccessControlService access){store=s;outbox=o;answers=a;vectors=v;events=e;this.access=access;}@GetMapping public ApiResponse<List<Dataset>> list(){RequestUser user=access.currentUser();List<Dataset> datasets=store.datasets();return ApiResponse.success(user.roles().contains("ADMIN")?datasets:datasets.stream().filter(d->user.datasetIds().contains(d.id())).toList());}@GetMapping("/{datasetId}")public ApiResponse<Dataset> get(@PathVariable long datasetId){access.requireDatasetAccess(datasetId);return ApiResponse.success(store.dataset(datasetId));}@PostMapping public ApiResponse<Dataset> create(@RequestBody Map<String,Object> b){access.requireRole("ADMIN");return ApiResponse.success(store.createDataset((String)b.get("name"),(String)b.get("description"),intValue(b,"chunkSize"),intValue(b,"chunkOverlap"),intValue(b,"topK"),doubleValue(b,"threshold","similarityThreshold")));}@PutMapping("/{datasetId}")public ApiResponse<Dataset> update(@PathVariable long datasetId,@RequestBody Map<String,Object> body){access.requireRole("ADMIN");Dataset before=store.dataset(datasetId);Dataset updated=store.updateDataset(datasetId,(String)body.get("name"),(String)body.get("description"),intOr(body,"chunkSize",before.chunkSize()),intOr(body,"chunkOverlap",before.chunkOverlap()),intOr(body,"topK",before.topK()),doubleOr(body,doubleValue(body,"threshold","similarityThreshold"),before.threshold()));answers.invalidateDataset(datasetId);if(before.chunkSize()!=updated.chunkSize()||before.chunkOverlap()!=updated.chunkOverlap())events.publishEvent(new ReembedDatasetEvent(datasetId));return ApiResponse.success(updated);}@DeleteMapping("/{datasetId}")public ApiResponse<Void> delete(@PathVariable long datasetId){access.requireRole("ADMIN");store.chunks(datasetId).forEach(c->outbox.append("DELETE_CHUNK",datasetId,c.documentId(),c.id(),"{}"));store.documents(datasetId).forEach(d->vectors.deleteDocument(d.id()));store.deleteDataset(datasetId);answers.invalidateDataset(datasetId);return ApiResponse.success(null);}@PostMapping("/{datasetId}/rebuild-index")public ApiResponse<Map<String,Integer>> rebuild(@PathVariable long datasetId){access.requireRole("ADMIN");store.dataset(datasetId);events.publishEvent(new ReembedDatasetEvent(datasetId));return ApiResponse.success(Map.of("documents",store.documents(datasetId).size(),"requeued",outbox.requeueDataset(datasetId)));}private Integer intValue(Map<String,Object> body,String key){Object value=body.get(key);return value instanceof Number number?number.intValue():null;}private Integer intOr(Map<String,Object> body,String key,int fallback){Integer value=intValue(body,key);return value==null?fallback:value;}private Double doubleValue(Map<String,Object> body,String first,String second){Object value=body.containsKey(first)?body.get(first):body.get(second);return value instanceof Number number?number.doubleValue():null;}private Double doubleOr(Map<String,Object> body,Double value,double fallback){return value==null?fallback:value;}}
